48	    [HttpGet("{id:int}")]
49	    public async Task<ActionResult<EventDetailDto>> GetEvent(int id, CancellationToken ct)
50	    {
51	        var detail = await eventDetailService.GetEventDetailAsync(id, ct);
52	        if (detail is null)
53	        {
54	            return NotFound(new ErrorEnvelopeDto("EVENT_NOT_FOUND", "Veranstaltung nicht gefunden."));
