102	    ```typescript
103	    import { Component, inject, signal } from '@angular/core';
104	    import { ActivatedRoute } from '@angular/router';
105	    import { DatePipe } from '@angular/common';
106	    import { HttpErrorResponse } from '@angular/common/http';
107	
108	    import { EventsApiService } from '../../core/api/events-api.service';
109	    import { EventDetail } from '../../core/api/event-detail';
110	
111	    @Component({
112	      selector: 'app-event-detail',
113	      imports: [DatePipe],
114	      templateUrl: './event-detail.html',
115	      styleUrl: './event-detail.scss'
116	    })
117	    export class EventDetailPage {
118	      private readonly route = inject(ActivatedRoute);
119	      private readonly eventsApi = inject(EventsApiService);
120	
121	      readonly event = signal<EventDetail | null>(null);
122	      readonly loading = signal(true);
123	      readonly notFound = signal(false);
124	      readonly loadError = signal(false);
125	
126	      constructor() {
127	        const id = Number(this.route.snapshot.paramMap.get('id'));
128	        if (!Number.isInteger(id)) {
129	          this.loading.set(false);
130	          this.notFound.set(true);
131	          return;
132	        }
133	
134	        this.eventsApi.getEvent(id).subscribe({
135	          next: event => {
136	            this.event.set(event);
137	            this.loading.set(false);
138	          },
139	          error: (err: HttpErrorResponse) => {
140	            this.loading.set(false);
141	            if (err.error?.code === 'EVENT_NOT_FOUND') {
142	              this.notFound.set(true);
143	            } else {
144	              this.loadError.set(true);
145	            }
146	          }
147	        });
148	      }
149	    }
150	    ```
151	    Route-Parameter wird bewusst per `route.snapshot.paramMap.get('id')` im Konstruktor gelesen, nicht reaktiv (kein `toSignal(route.paramMap)`) `[ANNAHME]`: Diese Seite ist im gesamten IA-Baum (`EXPERIENCE.md` → Information Architecture) nur von `event-card` aus erreichbar, es gibt keinen Link von einer Detailseite zu einer anderen — ein Navigations-Fall, bei dem Angular dieselbe Komponenteninstanz mit geändertem `id`-Parameter wiederverwendet, kommt in dieser Anwendung nicht vor. `provideRouter` in `app.config.ts` nutzt kein `withComponentInputBinding()`, daher kein `@Input() id`-Pattern verfügbar/etabliert — `ActivatedRoute` ist der einzige Weg.
152	    Fehlerunterscheidung nach `err.error?.code`, nicht nach `message` oder HTTP-Status — folgt AD-7 ("Frontend schaltet ausschließlich auf `code`, nie auf `message`") und ist bereits jetzt so anzulegen, auch wenn diese Story der erste Ort ist, an dem ein Fehlercode überhaupt im Frontend ausgewertet wird.
