156	      <p class="event-detail__loading">Veranstaltung wird geladen…</p>
157	    } @else if (notFound()) {
158	      <p class="event-detail__error" role="alert">Veranstaltung nicht gefunden.</p>
159	    } @else if (loadError()) {
160	      <p class="event-detail__error" role="alert">Veranstaltungsdetails konnten nicht geladen werden. Bitte versuchen Sie es später erneut.</p>
161	    } @else if (event(); as e) {
162	      <article class="event-detail">
163	        <h1 class="event-detail__title">{{ e.titel }}</h1>
164	        <p class="event-detail__description">{{ e.beschreibung }}</p>
165	        <dl class="event-detail__meta">
166	          <dt>Spielstätte</dt>
167	          <dd>{{ e.spielstaette }}</dd>
168	          <dt>Raum</dt>
169	          <dd>{{ e.raum }}</dd>
170	          <dt>Zeitpunkt</dt>
171	          <dd>{{ e.zeitpunkt | date:'EEEE, d. MMMM y, HH:mm' }} Uhr</dd>
172	          <dt>Dauer</dt>
173	          <dd>{{ e.dauerMinuten }} Minuten</dd>
174	          <dt>Altersfreigabe</dt>
