26	+using Microsoft.EntityFrameworkCore;
27	+using seed_a_backend.Api.Infrastructure;
28	+
29	+namespace seed_a_backend.Api.Application;
30	+
31	+/// <summary>
32	+/// `Domain/Room` und `Domain/Venue` haben keine Navigationseigenschaft zurück zum Elternobjekt
33	+/// (alle Beziehungen sind in `AppDbContext` einseitig mit `.WithOne()` ohne Inverse konfiguriert),
34	+/// daher ein expliziter Join über die FK-Spalten statt `.Include()`. `Event.PriceCategories` ist
35	+/// dagegen eine echte Navigationseigenschaft, dafür ist kein zusätzlicher Join nötig.
36	+/// </summary>
37	+public class EventDetailService(AppDbContext db)
38	+{
39	+    public async Task<EventDetail?> GetEventDetailAsync(int id, CancellationToken ct = default) =>
40	+        await (
41	+            from e in db.Events
42	+            join r in db.Rooms on e.RoomId equals r.Id
43	+            join v in db.Venues on r.VenueId equals v.Id
44	+            where e.Id == id
45	+            select new EventDetail(
46	+                e.Id, e.Titel, e.Beschreibung, e.DauerMinuten, e.Altersfreigabe,
47	+                v.Name, r.Name, e.Zeitpunkt,
48	+                e.PriceCategories.OrderBy(pc => pc.Id)
49	+                    .Select(pc => new PriceCategorySummary(pc.Id, pc.Name, pc.Preis)).ToList())
50	+        ).SingleOrDefaultAsync(ct);
51	+}
