578	+import { Component, inject, signal } from '@angular/core';
579	+import { ActivatedRoute } from '@angular/router';
580	+import { DatePipe } from '@angular/common';
581	+import { HttpErrorResponse } from '@angular/common/http';
582	+
583	+import { EventsApiService } from '../../core/api/events-api.service';
584	+import { EventDetail } from '../../core/api/event-detail';
585	+
586	+@Component({
587	+  selector: 'app-event-detail',
588	+  imports: [DatePipe],
589	+  templateUrl: './event-detail.html',
590	+  styleUrl: './event-detail.scss'
591	+})
592	+export class EventDetailPage {
593	+  private readonly route = inject(ActivatedRoute);
594	+  private readonly eventsApi = inject(EventsApiService);
595	+
596	+  readonly event = signal<EventDetail | null>(null);
597	+  readonly loading = signal(true);
598	+  readonly notFound = signal(false);
599	+  readonly loadError = signal(false);
600	+
601	+  constructor() {
602	+    const id = Number(this.route.snapshot.paramMap.get('id'));
603	+    if (!Number.isInteger(id)) {
604	+      this.loading.set(false);
605	+      this.notFound.set(true);
606	+      return;
607	+    }
608	+
609	+    this.eventsApi.getEvent(id).subscribe({
610	+      next: event => {
611	+        this.event.set(event);
612	+        this.loading.set(false);
613	+      },
614	+      error: (err: HttpErrorResponse) => {
615	+        this.loading.set(false);
616	+        if (err.error?.code === 'EVENT_NOT_FOUND') {
617	+          this.notFound.set(true);
618	+        } else {
619	+          this.loadError.set(true);
620	+        }
621	+      }
622	+    });
623	+  }
624	+}
